// INCOME ANALYSIS — what arrives, how regularly, and how much it MOVES.
//
// The variance is the part that matters, and it is the part a mean destroys. Two people earning
// $4,000 a month on average are in completely different situations if one is salaried and the other
// invoices lumpily — the second has months that do not cover rent, and an average says nothing about
// them. Every downstream question (runway, what payment is sustainable, whether a balance transfer is
// safe) turns on the low months, not the typical one.
//
// So this reports a MEDIAN and a SPREAD per source, and classifies stability rather than collapsing
// everything to one number that reads as more certain than it is.
import { type Money, money, sum } from "@/features/finance/lib/money";
import { type Txn, daysBetween, merchantKey, monthOf } from "@/features/finance/lib/txn";

export type IncomeCadence = "weekly" | "biweekly" | "semimonthly" | "monthly" | "irregular";

/** How much a source can be relied on, which is a different question from how much it pays. */
export type Stability = "steady" | "variable" | "lumpy";

export interface IncomeSource {
  readonly key: string;
  /** The most recent description, so a person recognises it. */
  readonly label: string;
  readonly account: string;
  readonly cadence: IncomeCadence;
  /** MEDIAN receipt — not the mean. One large invoice must not move the figure everything else
   *  depends on. */
  readonly typical: Money;
  /** The smallest receipt observed. What a bad month actually looked like, which is the number a
   *  runway calculation should be using. */
  readonly low: Money;
  readonly high: Money;
  readonly occurrences: number;
  readonly firstSeen: string;
  readonly lastSeen: string;
  /** 0-1. How close the receipts are to each other; 1 is identical every time. */
  readonly consistency: number;
  readonly stability: Stability;
  /** Typical amount scaled to a month at this cadence — comparable across sources. */
  readonly monthlyEquivalent: Money;
}

export interface IncomeAnalysis {
  readonly sources: readonly IncomeSource[];
  /** Median TOTAL across whole months observed. The honest "usual month". */
  readonly typicalMonth: Money;
  /** The worst whole month observed. What the plan has to survive. */
  readonly worstMonth: Money;
  readonly bestMonth: Money;
  /** Whole months the analysis is computed over. A figure from two months is not an income pattern,
   *  and stating the coverage is what stops it being read as one. */
  readonly monthsObserved: number;
  /** Inbound money that matched no repeating source — one-offs, transfers, refunds. Reported rather
   *  than folded in: a tax refund is not income you can plan on receiving again. */
  readonly oneOff: readonly Txn[];
}

const PER_MONTH: Record<Exclude<IncomeCadence, "irregular">, number> = {
  weekly: 52 / 12,
  biweekly: 26 / 12,
  semimonthly: 2,
  monthly: 1,
};

const CADENCE_DAYS: [Exclude<IncomeCadence, "irregular">, number, number][] = [
  ["weekly", 7, 2],
  ["biweekly", 14, 3],
  // Twice a month (the 1st and 15th) averages ~15.2 days and is NOT biweekly — 24 payments a year
  // against 26. Treating one as the other misstates annual income by two whole payments.
  ["semimonthly", 15, 2],
  ["monthly", 30, 5],
];

const median = (xs: number[]): number => {
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : Math.round((s[m - 1] + s[m]) / 2);
};

function classifyCadence(gaps: number[]): IncomeCadence {
  if (gaps.length < 1) return "irregular";
  const typical = median(gaps);

  // SEMIMONTHLY vs BIWEEKLY — a median cannot separate these, and getting it wrong costs two whole
  // payments a year (24 against 26), which is a month and a half of rent hidden inside the
  // arithmetic. Pay on the 1st and 15th and the gaps ALTERNATE 14 / 16-17, whose median lands right
  // where biweekly lives. Pay every fortnight and the gaps are CONSTANT at 14. That constancy is the
  // discriminator, so it is what this checks rather than the average.
  if (typical >= 13 && typical <= 17) {
    const spread = Math.max(...gaps) - Math.min(...gaps);
    return spread >= 2 ? "semimonthly" : "biweekly";
  }
  return CADENCE_DAYS.find(([, days, tol]) => Math.abs(typical - days) <= tol)?.[0] ?? "irregular";
}

/** Consistency is how tightly receipts cluster on the median, as a 0-1 score. */
function consistencyOf(amounts: number[]): number {
  const mid = median(amounts);
  if (mid === 0) return 0;
  const spread = amounts.reduce((a, v) => a + Math.abs(v - mid), 0) / amounts.length;
  return Math.max(0, Math.min(1, 1 - spread / mid));
}

/** The thresholds are judgements, named so they can be argued with rather than reverse-engineered. */
function stabilityOf(consistency: number): Stability {
  if (consistency >= 0.9) return "steady";
  if (consistency >= 0.6) return "variable";
  return "lumpy";
}

export interface IncomeOptions {
  /** Fewest receipts before a source counts as a source rather than a one-off. */
  readonly minOccurrences?: number;
}

export function analyseIncome(
  txns: readonly Txn[],
  currency: string,
  opts: IncomeOptions = {},
): IncomeAnalysis {
  const { minOccurrences = 3 } = opts;
  const inbound = txns.filter((t) => t.amount.minor > 0);

  const groups = new Map<string, Txn[]>();
  for (const t of inbound) {
    const key = merchantKey(t.description);
    if (!key) continue;
    // SEPARATED BY A NUL, not a space, because a merchant key is several words and an account
    // name commonly holds one too ("Chase Freedom"). A space separator makes the join
    // ambiguous, and splitting it back apart then hands the caller a key with account text
    // inside it. A NUL cannot occur in either half, so the split is exact.
    const id = `${t.account}\0${key}`;
    const bucket = groups.get(id);
    if (bucket) bucket.push(t);
    else groups.set(id, [t]);
  }

  const sources: IncomeSource[] = [];
  const claimed = new Set<Txn>();
  for (const [id, rows] of groups) {
    if (rows.length < minOccurrences) continue;
    const sorted = [...rows].sort((a, b) => a.date.localeCompare(b.date));
    const gaps: number[] = [];
    for (let i = 1; i < sorted.length; i++) gaps.push(daysBetween(sorted[i - 1].date, sorted[i].date));
    const cadence = classifyCadence(gaps);
    if (cadence === "irregular") continue;

    const amounts = sorted.map((t) => t.amount.minor);
    const consistency = Math.round(consistencyOf(amounts) * 100) / 100;
    const typical = money(median(amounts), currency);
    for (const t of sorted) claimed.add(t);

    sources.push({
      key: id.split("\0")[1],
      label: sorted[sorted.length - 1].description,
      account: sorted[0].account,
      cadence,
      typical,
      low: money(Math.min(...amounts), currency),
      high: money(Math.max(...amounts), currency),
      occurrences: sorted.length,
      firstSeen: sorted[0].date,
      lastSeen: sorted[sorted.length - 1].date,
      consistency,
      stability: stabilityOf(consistency),
      monthlyEquivalent: money(
        Math.round(typical.minor * PER_MONTH[cadence as Exclude<IncomeCadence, "irregular">]),
        currency,
      ),
    });
  }

  // WHOLE months only. A partial month at either end reads as a catastrophic drop and would drag the
  // worst-month figure — the one a plan is built on — to something that never happened.
  const byMonth = new Map<string, number>();
  for (const t of inbound) byMonth.set(monthOf(t.date), (byMonth.get(monthOf(t.date)) ?? 0) + t.amount.minor);
  const months = [...byMonth.keys()].sort();
  const whole = months.length > 2 ? months.slice(1, -1) : months;
  const totals = whole.map((m) => byMonth.get(m)!);

  return {
    sources: sources.sort((a, b) => b.monthlyEquivalent.minor - a.monthlyEquivalent.minor),
    typicalMonth: money(totals.length ? median(totals) : 0, currency),
    worstMonth: money(totals.length ? Math.min(...totals) : 0, currency),
    bestMonth: money(totals.length ? Math.max(...totals) : 0, currency),
    monthsObserved: totals.length,
    oneOff: inbound.filter((t) => !claimed.has(t)),
  };
}

/** Every source's monthly equivalent, together. */
export const expectedMonthly = (a: IncomeAnalysis, currency: string): Money =>
  sum(a.sources.map((s) => s.monthlyEquivalent), currency);

