import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import { analyseIncome, expectedMonthly } from "@/features/finance/lib/income";
import type { Txn } from "@/features/finance/lib/txn";

// SYNTHETIC FIXTURES ONLY.
const usd = (major: number): Money => fromMajor(major, "USD");
const inc = (date: string, description: string, major: number, account = "checking"): Txn => ({
  date,
  description,
  amount: usd(Math.abs(major)),
  account,
});

/** A salary on the 1st and 15th of each month — 24 a year, not 26. */
const semimonthly = (major: number, months = 6): Txn[] => {
  const out: Txn[] = [];
  for (let m = 1; m <= months; m++) {
    const mm = String(m).padStart(2, "0");
    out.push(inc(`2026-${mm}-01`, "EMPLOYER PAYROLL DIRECT DEP", major));
    out.push(inc(`2026-${mm}-15`, "EMPLOYER PAYROLL DIRECT DEP", major));
  }
  return out;
};

describe("analyseIncome — the variance is the point", () => {
  it("reports a MEDIAN, so one big month does not move the figure", () => {
    // A mean would let a single large invoice raise the "typical" month above anything that has ever
    // actually happened, and every downstream plan would be built on it.
    const lumpy = [
      inc("2026-01-10", "CLIENT ALPHA INVOICE", 1000),
      inc("2026-02-10", "CLIENT ALPHA INVOICE", 1200),
      inc("2026-03-10", "CLIENT ALPHA INVOICE", 900),
      inc("2026-04-10", "CLIENT ALPHA INVOICE", 9000),
    ];
    const [s] = analyseIncome(lumpy, "USD").sources;
    expect(s.typical.minor).toBe(110000); // median of 900/1000/1200/9000 -> (1000+1200)/2
    expect(s.high.minor).toBe(900000);
    expect(s.low.minor).toBe(90000);
  });

  it("separates STEADY from LUMPY at the same average", () => {
    // The whole reason this capability exists. Same money, completely different situations.
    const steady = analyseIncome(semimonthly(2000), "USD").sources[0];
    const lumpy = analyseIncome(
      [
        inc("2026-01-05", "CLIENT WORK PAYMENT", 500),
        inc("2026-02-05", "CLIENT WORK PAYMENT", 6000),
        inc("2026-03-05", "CLIENT WORK PAYMENT", 400),
        inc("2026-04-05", "CLIENT WORK PAYMENT", 5100),
      ],
      "USD",
    ).sources[0];
    expect(steady.stability).toBe("steady");
    expect(lumpy.stability).toBe("lumpy");
    expect(steady.consistency).toBeGreaterThan(lumpy.consistency);
  });

  it("reports the WORST whole month, which is what a plan has to survive", () => {
    const rows = [
      ...semimonthly(2000, 4),
      inc("2026-03-20", "SIDE WORK PAYMENT", 0.0), // a zero adds nothing
    ];
    const a = analyseIncome(rows, "USD");
    expect(a.worstMonth.minor).toBeLessThanOrEqual(a.typicalMonth.minor);
    expect(a.typicalMonth.minor).toBeLessThanOrEqual(a.bestMonth.minor);
  });
});

describe("analyseIncome — cadence", () => {
  it("does NOT call a semimonthly salary biweekly", () => {
    // 24 payments a year against 26. Treating one as the other misstates annual income by two whole
    // payments — a month and a half of rent, invisible in the arithmetic.
    const [s] = analyseIncome(semimonthly(2000), "USD").sources;
    expect(s.cadence).toBe("semimonthly");
    expect(s.monthlyEquivalent.minor).toBe(200000 * 2);
  });

  it("recognises a true biweekly deposit — CONSTANT gaps, not alternating", () => {
    // The other side of the same discrimination. Every fortnight is a constant 14; the 1st and 15th
    // alternate. Only the second is semimonthly.
    const rows: Txn[] = [];
    const start = Date.UTC(2026, 0, 2);
    for (let i = 0; i < 8; i++) {
      rows.push(inc(new Date(start + i * 14 * 86_400_000).toISOString().slice(0, 10), "PAYROLL", 1500));
    }
    const [s] = analyseIncome(rows, "USD").sources;
    expect(s.cadence).toBe("biweekly");
    // 26 a year, not 24 — the difference this test exists to protect.
    expect(s.monthlyEquivalent.minor).toBe(Math.round(150000 * (26 / 12)));
  });

  it("does not treat an irregular trickle as a source", () => {
    const random = ["2026-01-03", "2026-01-27", "2026-04-11", "2026-04-19"].map((d) =>
      inc(d, "MARKETPLACE PAYOUT", 60),
    );
    expect(analyseIncome(random, "USD").sources).toEqual([]);
  });
});

describe("analyseIncome — what it refuses to fold in", () => {
  it("keeps a ONE-OFF out of the sources rather than treating it as income", () => {
    // A tax refund is not income you can plan on receiving again, and folding it in would raise the
    // expected month by money that is never coming back.
    const rows = [...semimonthly(2000, 4), inc("2026-03-02", "STATE TAX REFUND", 1400)];
    const a = analyseIncome(rows, "USD");
    expect(a.sources).toHaveLength(1);
    expect(a.oneOff.map((t) => t.description)).toContain("STATE TAX REFUND");
  });

  it("ignores OUTBOUND money entirely", () => {
    const rows = [...semimonthly(2000, 4), { date: "2026-02-04", description: "RENT", amount: usd(-1450), account: "checking" }];
    expect(analyseIncome(rows, "USD").sources).toHaveLength(1);
  });

  it("states how many whole months it saw", () => {
    // A figure from two months is not an income pattern. Saying the coverage is what stops it being
    // read as one.
    const a = analyseIncome(semimonthly(2000, 6), "USD");
    expect(a.monthsObserved).toBeGreaterThan(0);
    expect(a.monthsObserved).toBeLessThanOrEqual(6);
  });

  it("survives having no income at all without inventing any", () => {
    const a = analyseIncome([], "USD");
    expect(a.sources).toEqual([]);
    expect(a.typicalMonth.minor).toBe(0);
    expect(a.monthsObserved).toBe(0);
    expect(expectedMonthly(a, "USD").minor).toBe(0);
  });
});

describe("expectedMonthly", () => {
  it("adds every source's monthly equivalent", () => {
    const rows = [
      ...semimonthly(2000, 5),
      ...Array.from({ length: 5 }, (_, i) => inc(`2026-0${i + 1}-20`, "SIDE CONTRACT PAYMENT", 400, "checking")),
    ];
    const a = analyseIncome(rows, "USD");
    expect(a.sources).toHaveLength(2);
    expect(expectedMonthly(a, "USD").minor).toBe(200000 * 2 + 40000);
  });
});

describe("the source key identifies the MERCHANT, never the account", () => {
  // An account name with a space in it is the common case, not the corner: "Chase Freedom",
  // "Ally Savings", "BofA Checking". Joining account and merchant key with a space makes the pair
  // ambiguous, and cutting it back apart at the first space then leaks account text into the key —
  // so the identity a caller matches a source on across runs depends on what the account is called.
  it("does not leak an account name containing a space into the key", () => {
    const rows = semimonthly(2000, 5).map((t) => ({ ...t, account: "Chase Freedom" }));
    const a = analyseIncome(rows, "USD");
    expect(a.sources).toHaveLength(1);
    expect(a.sources[0].account).toBe("Chase Freedom");
    expect(a.sources[0].key).not.toContain("Freedom");
    expect(a.sources[0].key).not.toContain("Chase");
  });

  it("gives the same key for the same merchant on two differently-named accounts", () => {
    const one = analyseIncome(semimonthly(2000, 5).map((t) => ({ ...t, account: "Chase Freedom" })), "USD");
    const two = analyseIncome(semimonthly(2000, 5).map((t) => ({ ...t, account: "ally" })), "USD");
    expect(one.sources[0].key).toBe(two.sources[0].key);
    // Still two distinct sources, because a paycheque into two accounts is two standing arrangements.
    expect(one.sources[0].account).not.toBe(two.sources[0].account);
  });

  it("keeps the whole merchant key, not just its first word", () => {
    const rows = semimonthly(2000, 5).map((t) => ({ ...t, description: "NORTHWIND TRADING PAYROLL" }));
    const a = analyseIncome(rows, "USD");
    expect(a.sources[0].key.split(" ").length).toBeGreaterThan(1);
    expect(a.sources[0].key).toContain("northwind");
  });
});
